SELECT * FROM content_actions
WHERE user_id=#{userId} AND entity_type=#{entityType} AND entity_id=#{entityId}
  AND action_type=#{actionType}

SELECT EXISTS(
    SELECT 1 FROM content_actions
    WHERE user_id=#{userId} AND entity_type=#{entityType} AND entity_id=#{entityId}
      AND action_type=#{actionType} AND action_status=1
)

SELECT COUNT(*) FROM content_actions
WHERE entity_type=#{entityType} AND entity_id=#{entityId}
  AND action_type=#{actionType} AND action_status=1
